# ===== 14 Анализ запросов =====
serp_by_q=collections.defaultdict(list)
sp=os.path.join(ROOT,'raw/serp/serp.tsv')
if os.path.exists(sp):
    for row in csv.DictReader(open(sp,encoding='utf-8'),delimiter='\t'):
        serp_by_q[row['query']].append(row)
PG={p['url']:p for p in PAGES if p.get('status')=='ok'}
an=[]
for q,rows in serp_by_q.items():
    urls=[r['url'] for r in rows]
    meas=[PG[u] for u in urls if u in PG]
    inf = sum(1 for u in urls if re.search(r'/blog|/stati|/article|/news',u))
    intent = 'информационный' if inf>=4 else ('коммерческий' if inf<=1 else 'смешанный')
    fmt = 'статья/гид' if intent=='информационный' else ('страница услуги' if intent=='коммерческий' else 'страница услуги с развёрнутым информационным блоком')
    page=next((r['query_id'] for r in SEM if r['norm']==re.sub(r'\s+',' ',q.lower().replace('ё','е'))), '')
    tgt=next((r['page'] for r in SEM if r['norm']==re.sub(r'\s+',' ',q.lower().replace('ё','е'))), 'см. «09 Семантика»')
    n_=len(meas)
    w=[p['words'] for p in meas]
    an.append((q,intent,fmt,tgt,'; '.join(p['content_id'] for p in meas) or '—',n_,
               f'{min(w)}–{max(w)} слов, медиана {round(statistics.median(w))}' if w else 'не измерено',
               f'Геозависимость: {"да" if re.search("подмосков|москв|истра",q) else "не подтверждена"}. Агрегаторы в топе: '+
               ('да ('+', '.join(sorted({r["domain"] for r in rows if re.search("avito|uslugi.yandex|2gis|zoon",r["domain"])}))+')' if any(re.search('avito|uslugi.yandex|2gis|zoon',r['domain']) for r in rows) else 'нет'),
               'нет' , 'проверено'))
