# ===== 17 Вхождения конкурентов =====
occ=[]
for q,rows in serp_by_q.items():
    qn=q.lower().replace('ё','е')
    for r in rows[:5]:
        p=PG.get(r['url'])
        if not p:
            occ.append((q,'—','точные вхождения, без учёта регистра, границы слов','','','','','','','','НЕ ИЗМЕРЕНО — страница недоступна для извлечения')); continue
        t=p['text'].lower().replace('ё','е')
        ex=len(re.findall(r'(?<![а-яa-z])'+re.escape(qn)+r'(?![а-яa-z])',t))
        title_hit=1 if qn in p['title'].lower().replace('ё','е') else 0
        h1_hit=1 if any(qn in x.lower().replace('ё','е') for x in p['h1']) else 0
        h2_hit=sum(1 for x in p['h2'] if qn in x.lower().replace('ё','е'))
        per100 = round(ex/p['words']*100,3) if p['words'] else ''
        occ.append((q,p['content_id'],'точные вхождения, без учёта регистра, нормализованные пробелы, границы слов',
                    ex,'не считались — морфологический анализатор не подключён',
                    f'Title: {title_hit}; H1: {h1_hit}; H2: {h2_hit}; основной текст: {ex}',
                    p['words'],per100,'не рассчитывалась',
                    'Диагностика, не норма. У лидеров точное вхождение часто отсутствует — задача раскрыта синонимами','измерено'))
